"use client";
import { useEffect, useRef, useState } from "react";
import "./copy-button.css";

/** Copies text with one click; the icon morphs to a check and the result is announced. */
export function CopyButton({
  value,
  label = "Copy",
  className = "",
}: {
  value: string;
  label?: string;
  className?: string;
}) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  return (
    <button
      type="button"
      className={`forme-copy ${className}`}
      data-state={state}
      aria-label={state === "copied" ? "Copied" : label}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(value);
          setState("copied");
        } catch {
          setState("failed");
        }
        clearTimeout(timer.current);
        timer.current = setTimeout(() => setState("idle"), 1600);
      }}
    >
      <svg viewBox="0 0 24 24" aria-hidden="true" className="forme-copy-icon is-copy">
        <rect x="8" y="8" width="12" height="12" rx="2.5" />
        <path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2" />
      </svg>
      <svg viewBox="0 0 24 24" aria-hidden="true" className="forme-copy-icon is-check">
        <path d="m5 12.5 4.5 4.5L19 7.5" />
      </svg>
      <span className="forme-copy-status" role="status">
        {state === "copied" ? "Copied" : state === "failed" ? "Copy failed" : ""}
      </span>
    </button>
  );
}

.forme-copy {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 0;
  border-radius: 10px;
  background: color-mix(in srgb, currentColor 7%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 12%, transparent);
  color: inherit;
  cursor: pointer;
  transition:
    background 0.2s,
    transform 0.15s;
}
.forme-copy:hover {
  background: color-mix(in srgb, currentColor 12%, transparent);
}
.forme-copy:active {
  transform: scale(0.94);
}
.forme-copy:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}
.forme-copy-icon {
  grid-area: 1 / 1;
  width: 17px;
  height: 17px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.7;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition:
    opacity 0.25s,
    transform 0.35s cubic-bezier(0.3, 1.4, 0.5, 1),
    filter 0.25s;
}
.forme-copy-icon.is-check {
  color: #22c55e;
  opacity: 0;
  transform: scale(0.4);
  filter: blur(4px);
}
.forme-copy[data-state="copied"] .is-copy {
  opacity: 0;
  transform: scale(0.4);
  filter: blur(4px);
}
.forme-copy[data-state="copied"] .is-check {
  opacity: 1;
  transform: none;
  filter: none;
}
.forme-copy[data-state="failed"] {
  box-shadow: inset 0 0 0 1px #ef4444;
}
.forme-copy-status {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
@media (prefers-reduced-motion: reduce) {
  .forme-copy,
  .forme-copy-icon {
    transition: none;
  }
}
